def string_transformation(A: str, B: str, rules: list):
    """
    Perform string transformation from A to B using a set of transformation rules.
    Applies BFS up to 10 steps and returns the minimum number of steps required.
    If impossible within 10 steps, returns "NO ANSWER!".
    """
    # Basic input validation
    if not isinstance(A, str) or not isinstance(B, str):
        return "NO ANSWER!"
    if not isinstance(rules, list):
        return "NO ANSWER!"
    # Validate each rule is a tuple of two strings
    for r in rules:
        if (
            not isinstance(r, tuple)
            or len(r) != 2
            or not isinstance(r[0], str)
            or not isinstance(r[1], str)
        ):
            return "NO ANSWER!"

    # BFS initialization
    visited = {A}
    queue = [(A, 0)]
    max_steps = 10

    while queue:
        current, steps = queue.pop(0)
        if current == B:
            return steps
        if steps >= max_steps:
            continue
        for src, tgt in rules:
            start = 0
            while True:
                pos = current.find(src, start)
                if pos == -1:
                    break
                new_str = current[:pos] + tgt + current[pos + len(src) :]
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, steps + 1))
                start = pos + 1  # allow overlapping matches

    return "NO ANSWER!"

def is_prime(num: int) -> bool:
    """
    Determine whether a given integer is a prime number.

    Parameters:
    num (int): The integer to check for primality.

    Returns:
    bool: True if `num` is a prime number, False otherwise.
    """
    if not isinstance(num, int):
        raise TypeError("num must be an integer")
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    max_factor = int(num**0.5) + 1
    while i <= max_factor:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0
    # Longest increasing subsequence ending at each position
    inc = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and inc[j] + 1 > inc[i]:
                inc[i] = inc[j] + 1
    # Longest decreasing subsequence starting from each position
    dec = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and dec[j] + 1 > dec[i]:
                dec[i] = dec[j] + 1
    # Max length of bitonic subsequence
    max_bitonic = 0
    for i in range(n):
        bitonic_len = inc[i] + dec[i] - 1
        if bitonic_len > max_bitonic:
            max_bitonic = bitonic_len
    return n - max_bitonic
